// Brasswork menu art components. Art: public/brasswork/art, generated by scripts/brasswork/build-menu-art.py.
import type { CSSProperties, ReactNode } from "react";
import {
    DECOR, EMPTY_SCENES, EMPTY_SHEET, PORTRAIT_SHEET, RARITY_FRAMES, portraitCell, rarityOf,
    type EmptyScene, type Rarity,
} from "@/lib/automation/art";
import "./art.css";

export { rarityOf, RARITY_FRAMES };
export type { Rarity };

/** A panel wrapped in pixel corner brackets. `rarity` swaps the bracket metal and gems. */
export function ArtPanel({ rarity, children, className, style }: {
    rarity?: Rarity; children: ReactNode; className?: string; style?: CSSProperties;
}) {
    const url = rarity ? RARITY_FRAMES[rarity].url : DECOR.frame.url;
    return (
        <div className={`bwa-panel ${className ?? ""}`} style={{ ...style, ["--bwa-frame" as string]: `url("${url}")` }}>
            {children}
        </div>
    );
}

/** Panel title on a riveted brass plate with gear end caps. */
export function PanelTitle({ children, as: Tag = "h2" }: { children: ReactNode; as?: "h2" | "h3" | "div" }) {
    return <Tag className="bwa-title" style={{ ["--bwa-header" as string]: `url("${DECOR.header.url}")` }}>{children}</Tag>;
}

/** Engraved double rule with a gear in the middle. */
export function ArtDivider() {
    return (
        <div className="bwa-divider" aria-hidden>
            <i style={{ backgroundImage: `url("${DECOR.rule.url}")` }} />
            <b style={{ backgroundImage: `url("${DECOR.gear.url}")` }} />
            <i style={{ backgroundImage: `url("${DECOR.rule.url}")` }} />
        </div>
    );
}

/** Machine portrait on its lamplit bench. size is CSS px (art is 128). */
export function MachinePortrait({ id, size = 128, label }: { id: string; size?: number; label?: string }) {
    const cell = portraitCell(id);
    if (cell === undefined) return null;
    const { cols, rows, url } = PORTRAIT_SHEET;
    const col = cell % cols, row = Math.floor(cell / cols);
    return (
        <span
            className="bwa-portrait"
            role={label ? "img" : undefined}
            aria-label={label}
            aria-hidden={label ? undefined : true}
            style={{
                ["--bwa-size" as string]: `${size}px`,
                backgroundImage: `url("${url}")`,
                backgroundSize: `${cols * size}px ${rows * size}px`,
                backgroundPosition: `${-col * size}px ${-row * size}px`,
            }}
        />
    );
}

/** Dial gauge; value 0..1 sweeps the needle over 270 degrees. */
export function ArtGauge({ value, size = 64, label }: { value: number; size?: number; label?: string }) {
    const v = Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
    return (
        <span className="bwa-gauge" role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(v * 100)}
            aria-label={label} style={{ ["--bwa-size" as string]: `${size}px` }}>
            <img src={DECOR.gauge.url} alt="" />
            <img src={DECOR.needle.url} alt="" style={{ transform: `rotate(${-135 + 270 * v}deg)` }} />
        </span>
    );
}

/** Empty list illustration with a short line under it. */
export function EmptyState({ scene, children }: { scene: EmptyScene; children?: ReactNode }) {
    const i = EMPTY_SCENES[scene];
    return (
        <div className="bwa-empty">
            <span aria-hidden style={{
                backgroundImage: `url("${EMPTY_SHEET.url}")`,
                backgroundSize: `${3 * 192}px 144px`,
                backgroundPosition: `${-i * 192}px 0`,
            }} />
            {children ? <span>{children}</span> : null}
        </div>
    );
}
